const TURN_RATE=5.5,PROTECT_TURN_RATE=3.6,clamp=(v,min,max)=>Math.min(max,Math.max(min,v));function wrapAngle(a){while(a>Math.PI)a-=Math.PI*2;while(a<-Math.PI)a+=Math.PI*2;return a}function moveToward(a,b,d){return a<b?Math.min(b,a+d):Math.max(b,a-d)}function unit(x,y,fallbackX=1,fallbackY=0){const l=Math.hypot(x,y);return l>.01?{x:x/l,y:y/l}:{x:fallbackX,y:fallbackY}}
function steerInput(state,input,dt,magnitude,protecting){const x=input.moveX??0,y=input.moveY??0,current=state.steerAngle??Math.atan2(state.player.facingY,state.player.facingX);if(Math.hypot(x,y)<.01)return{input:{...input,moveX:0,moveY:0},angle:current};const desired=Math.atan2(y,x),rate=protecting?PROTECT_TURN_RATE:TURN_RATE,delta=wrapAngle(desired-current),next=current+clamp(delta,-rate*dt,rate*dt);return{input:{...input,moveX:Math.cos(next)*magnitude,moveY:Math.sin(next)*magnitude},angle:next}}
