export function createScenarioState(){return{...createFootball2DState(),...createOpponentState(FIELD),steerAngle:0,driveMagnitude:0,burstTime:0,burstBoostTime:0,burstX:1,burstY:0}}
export function stepScenario(s,i={},dt=1/60,tuning=DEFAULT_FEEL_TUNING,athletic=DEFAULT_ATHLETIC_PROFILE){const motion=getAthleticMotion(athletic),total=Math.min(Math.max(dt,0),.05),count=Math.max(1,Math.ceil(total/(1/90))),slice=total/count;let n={...s};for(let x=0;x<count;x++){const first=x===0;if(first&&i.burstTriggered&&n.possession&&!i.protecting){const dir=unit(i.burstX??i.moveX,i.burstY??i.moveY,n.player.facingX,n.player.facingY);n={...n,burstTime:motion.burstDuration,burstBoostTime:motion.burstBoostDuration,burstX:dir.x,burstY:dir.y}}const burst=n.burstTime>0,boost=n.burstBoostTime>0,protecting=!!i.protecting&&n.possession&&!burst,raw=clamp(Math.hypot(i.moveX??0,i.moveY??0),0,1),target=burst?1:protecting?Math.min(raw,.48):raw,rate=target>n.driveMagnitude?motion.accelerationPerSecond*(boost?motion.burstAccelerationScale:1):motion.decelerationPerSecond,drive=moveToward(n.driveMagnitude,target,rate*slice),shield=shieldDirection(n.player,n.defender),source=burst?{...i,moveX:n.burstX,moveY:n.burstY}:{...i},before={...n.ball},steer=steerInput(n,first?source:{...source,shootReleased:false,burstTriggered:false},slice,drive,protecting),maxSpeedScale=motion.maxSpeedScale*(boost?motion.burstMaxScale:1),modelInput={...steer.input,protecting,shieldX:shield.x,shieldY:shield.y,burstActive:burst,burstTriggered:first&&!!i.burstTriggered,burstX:n.burstX,burstY:n.burstY,maxSpeedScale};n={...stepFootball2D(n,modelInput,slice,tuning),steerAngle:steer.angle,driveMagnitude:drive,burstTime:Math.max(0,n.burstTime-slice),burstBoostTime:Math.max(0,n.burstBoostTime-slice),burstX:n.burstX,burstY:n.burstY};if(n.lastEvent==="burst_recovered")n={...n,burstTime:0,burstBoostTime:0};if(n.status==="goal")break;const d=stepOpponentAI({defender:n.defender,keeper:n.keeper,player:n.player,ball:n.ball,possession:n.possession,protecting,burstActive:burst},FIELD,slice);n={...n,defender:d.defender,keeper:d.keeper,ball:d.ball,possession:d.possession,lastEvent:d.event??n.lastEvent};const k=stepGoalkeeper(n.keeper,before,n.ball,FIELD,slice);n={...n,keeper:k.keeper,ball:k.ball,possession:k.event?false:n.possession,lastEvent:k.event??n.lastEvent}}return n}
